using LaboratoryDesktopApp.Models;
using LaboratoryDesktopApp.Theme;

namespace LaboratoryDesktopApp.Controls;

public class TestParameterForm : Form
{
    private readonly TextBox name=ThemeHelper.TextBox(),code=ThemeHelper.TextBox(),unit=ThemeHelper.TextBox(),reference=ThemeHelper.TextBox(),order=ThemeHelper.TextBox(); private readonly ComboBox type=new(); private readonly CheckBox required=new(){Text="Required",Checked=true,AutoSize=true},active=new(){Text="Active",Checked=true,AutoSize=true}; public TestParameter? Result{get;private set;}
    public TestParameterForm(TestParameter? p){Text=p==null?"Add Parameter":"Edit Parameter";StartPosition=FormStartPosition.CenterParent;Size=new Size(500,540);BackColor=AppTheme.Background;var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(22),ColumnCount=1,RowCount=8};root.RowStyles.Add(new RowStyle(SizeType.Absolute,36));for(int i=0;i<7;i++)root.RowStyles.Add(new RowStyle(SizeType.Absolute,56));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.Controls.Add(new Label{Text=Text,Font=AppTheme.PageTitle,Dock=DockStyle.Fill},0,0);Field(root,"Parameter Name *",name,1);Field(root,"Parameter Code *",code,2);type.DropDownStyle=ComboBoxStyle.DropDownList;type.Items.AddRange(new object[]{"Numeric","Text","Positive / Negative","Predefined Choices"});type.SelectedIndex=0;Field(root,"Result Data Type",type,3);Field(root,"Unit (demo)",unit,4);Field(root,"Reference Information (Demo only)",reference,5);Field(root,"Display Order",order,6);var row=new FlowLayoutPanel{Dock=DockStyle.Fill};row.Controls.Add(required);row.Controls.Add(active);root.Controls.Add(row,0,7);var footer=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};var save=ThemeHelper.Button("Save",true);var cancel=ThemeHelper.Button("Cancel");save.Click+=(_,_)=>{if(string.IsNullOrWhiteSpace(name.Text)||string.IsNullOrWhiteSpace(code.Text)){MessageBox.Show("Name and code are required.");return;}if(!int.TryParse(order.Text,out var n))n=1;Result=new(){Name=name.Text.Trim(),Code=code.Text.Trim(),DataType=type.Text,Unit=unit.Text.Trim(),ReferenceInfo=reference.Text.Trim(),DisplayOrder=n,IsRequired=required.Checked,IsActive=active.Checked};DialogResult=DialogResult.OK;Close();};cancel.Click+=(_,_)=>Close();footer.Controls.Add(save);footer.Controls.Add(cancel);root.Controls.Add(footer,0,8);Controls.Add(root);if(p!=null){name.Text=p.Name;code.Text=p.Code;unit.Text=p.Unit;reference.Text=p.ReferenceInfo;order.Text=p.DisplayOrder.ToString();type.SelectedItem=p.DataType;required.Checked=p.IsRequired;active.Checked=p.IsActive;}}
    private void Field(TableLayoutPanel root,string label,Control c,int row){var panel=new Panel{Dock=DockStyle.Fill};panel.Controls.Add(ThemeHelper.Label(label));c.Location=new Point(4,22);c.Width=410;c.Anchor=AnchorStyles.Left|AnchorStyles.Right|AnchorStyles.Top;panel.Resize+=(_,_)=>c.Width=panel.ClientSize.Width-8;panel.Controls.Add(c);root.Controls.Add(panel,0,row);}
